"""Regression tests against synthetic fixtures generated by real Repomix."""

from __future__ import annotations

import sys
import tempfile
import unittest
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1] / "src"))
from repomix_static_reconstructor.extractor import (  # noqa: E402
    UnmixError,
    detect_format,
    parse_markdown,
    parse_repomix,
    parse_xml,
    unmix_repomix,
)


FIXTURES = Path(__file__).resolve().parent / "fixtures" / "repomix-1.19.0"

EXPECTED_MAIN_CONTENT = {
    "README.md": "# Fixture README\n\nSynthetic repository used to validate Repomix reconstruction.",
    "docs/ambiguous.md": (
        "## File: not-a-real-entry.txt\n"
        "```text\n"
        "This line mimics a Repomix header and must stay inside the file.\n"
        "```"
    ),
    "src/app.py": "def add(a, b):\n    return a + b",
    "src/bom.txt": "BOM-prefixed line",
    "src/crlf.txt": "line one\r\nline two",
    "src/deep/nested/file.txt": "deep content",
    "src/empty.txt": "",
    "src/fences.md": (
        "Before fence.\n\n"
        "```python\n"
        'print("inner fence")\n'
        "```\n\n"
        "````\n"
        "nested four-backtick example\n"
        "````\n\n"
        "After fence."
    ),
    "src/no-newline.txt": "no trailing newline",
    "src/special.txt": "ampersand & less < greater > quote \" apostrophe '",
    "src/unicode.txt": "unicode: café ☕ 日本語",
    "src/with space.txt": "space in path",
}

MAIN_FIXTURES = (
    "markdown/repomix-output.md",
    "markdown-parsable/repomix-output.md",
    "xml/repomix-output.xml",
    "xml-parsable/repomix-output.xml",
    "json/repomix-output.json",
)


def read_fixture(relative_path: str, *, encoding: str = "utf-8-sig") -> str:
    with open(FIXTURES / relative_path, encoding=encoding, newline="") as handle:
        return handle.read()


def parse_fixture(relative_path: str):
    text = read_fixture(relative_path)
    format_type = detect_format(text)
    return format_type, parse_repomix(text, format_type)


class RepomixFixtureTests(unittest.TestCase):
    def setUp(self) -> None:
        self.tmp = tempfile.TemporaryDirectory()
        self.root = Path(self.tmp.name)

    def tearDown(self) -> None:
        self.tmp.cleanup()

    def test_all_real_formats_match_expected_content(self) -> None:
        for relative_path in MAIN_FIXTURES:
            with self.subTest(fixture=relative_path):
                _, entries = parse_fixture(relative_path)
                self.assertEqual(
                    {entry.original_path: entry.content for entry in entries},
                    EXPECTED_MAIN_CONTENT,
                )

    def test_format_detection_disambiguates_xml_from_markdown_headers(self) -> None:
        # The XML fixture's first file contains a line-start "## File:" header.
        self.assertEqual(detect_format(read_fixture("xml/repomix-output.xml")), "xml")
        self.assertEqual(
            detect_format(read_fixture("xml-parsable/repomix-output.xml")), "xml"
        )
        self.assertEqual(
            detect_format(read_fixture("markdown/repomix-output.md")), "markdown"
        )
        self.assertEqual(
            detect_format(read_fixture("json/repomix-output.json")), "json"
        )

    def test_first_structural_marker_wins_over_file_content(self) -> None:
        markdown = (
            "This file is a merged representation.\n\n"
            "## File: a.xml\n`````\n<repomix><files></files></repomix>\n`````\n"
        )
        self.assertEqual(detect_format(markdown), "markdown")

        xml = (
            "Custom header text\n"
            '<repomix><files><file path="a.txt">## File: fake\n</file></files></repomix>'
        )
        self.assertEqual(detect_format(xml), "xml")

    def test_full_reconstruction_matches_fixture_bytes(self) -> None:
        for index, relative_path in enumerate(MAIN_FIXTURES):
            with self.subTest(fixture=relative_path):
                output = self.root / f"out-{index}"
                result = unmix_repomix(FIXTURES / relative_path, output)
                self.assertEqual(set(result.extracted), set(EXPECTED_MAIN_CONTENT))
                for file_path, expected in EXPECTED_MAIN_CONTENT.items():
                    with self.subTest(file=file_path):
                        self.assertEqual(
                            (output / file_path).read_bytes(), expected.encode("utf-8")
                        )

    def test_markdown_fence_length_above_content_runs(self) -> None:
        _, entries = parse_fixture("edge/markdown/repomix-output.md")
        contents = {entry.original_path: entry.content for entry in entries}
        self.assertEqual(contents["five.md"], "before\n`````\nafter")
        self.assertEqual(contents["six.md"], "before\n``````\nafter")
        self.assertEqual(contents["ten.md"], "before\n``````````\nafter")
        self.assertEqual(contents["ends-fence.md"], "text ending with `````")
        self.assertEqual(contents["trailing-spaces.md"], "before\n`````  \nafter")

    def test_parsable_xml_entities_and_special_paths(self) -> None:
        format_type, entries = parse_fixture("edge/xml-parsable/repomix-output.xml")
        self.assertEqual(format_type, "xml")
        contents = {entry.original_path: entry.content for entry in entries}
        self.assertEqual(contents['amp&quote"name.txt'], "weird path")
        self.assertEqual(contents["ends-fence.md"], "text ending with `````")
        self.assertEqual(contents["trailing-spaces.md"], "before\n`````  \nafter")

    def test_default_xml_ambiguous_quote_path_is_rejected(self) -> None:
        with self.assertRaises(UnmixError) as caught:
            parse_fixture("edge/xml/repomix-output.xml")
        self.assertIn("--parsable-style", str(caught.exception))

    def test_line_numbered_exports_are_rejected(self) -> None:
        for relative_path in (
            "line-numbers/markdown.md",
            "line-numbers/xml.xml",
            "line-numbers/json.json",
        ):
            with self.subTest(fixture=relative_path):
                with self.assertRaises(UnmixError) as caught:
                    unmix_repomix(
                        FIXTURES / relative_path, self.root / "out", dry_run=True
                    )
                self.assertIn("line-number", str(caught.exception))

    def test_line_numbered_without_summary_is_detected_from_content(self) -> None:
        raw = "# Files\n\n## File: a.txt\n```\n1: only line\n```\n"
        with self.assertRaises(UnmixError) as caught:
            parse_repomix(raw, "markdown")
        self.assertIn("line-number", str(caught.exception))

    def test_export_bom_is_accepted_for_every_format(self) -> None:
        for relative_path in MAIN_FIXTURES:
            with self.subTest(fixture=relative_path):
                text = "\ufeff" + read_fixture(relative_path)
                format_type = detect_format(text)
                entries = parse_repomix(text, format_type)
                self.assertEqual(
                    {entry.original_path: entry.content for entry in entries},
                    EXPECTED_MAIN_CONTENT,
                )

    def test_bom_export_reconstructs_through_cli_path(self) -> None:
        source = self.root / "bom.md"
        source.write_bytes(
            b"\xef\xbb\xbf" + read_fixture("markdown/repomix-output.md").encode()
        )
        output = self.root / "out"
        result = unmix_repomix(source, output)
        self.assertEqual(result.format_type, "markdown")
        self.assertEqual(
            (output / "src/app.py").read_text(), EXPECTED_MAIN_CONTENT["src/app.py"]
        )

    def test_crlf_export_structure_preserves_content_line_endings(self) -> None:
        markdown = "## File: a.txt\r\n```\r\nline1\r\nline2\r\n```\r\n"
        self.assertEqual(detect_format(markdown), "markdown")
        self.assertEqual(parse_markdown(markdown)[0].content, "line1\r\nline2")

        xml = '<files>\r\n<file path="a.txt">\r\nline1\r\nline2\r\n</file>\r\n</files>\r\n'
        self.assertEqual(detect_format(xml), "xml")
        self.assertEqual(parse_xml(xml)[0].content, "line1\r\nline2")

    def test_parsable_xml_with_custom_header_still_decodes_entities(self) -> None:
        raw = (
            "Custom header text\n"
            '<repomix><files><file path="a.txt">a &amp; b</file></files></repomix>'
        )
        self.assertEqual(parse_xml(raw)[0].content, "a & b")

    def test_default_xml_content_named_repomix_is_not_treated_as_parsable(self) -> None:
        raw = '<files>\n<file path="a.txt">\n<repomix>\n</file>\n</files>'
        self.assertEqual(parse_xml(raw)[0].content, "<repomix>")

    def test_parsable_xml_does_not_strip_content_newlines(self) -> None:
        parsable = '<repomix><files><file path="a.txt">\nfirst</file></files></repomix>'
        default = '<files>\n<file path="a.txt">\n\nfirst\n</file>\n</files>'
        self.assertEqual(parse_xml(parsable)[0].content, "\nfirst")
        self.assertEqual(parse_xml(default)[0].content, "\nfirst")

    def test_parsable_xml_decodes_entities_once(self) -> None:
        raw = (
            '<repomix><files><file path="a.txt">'
            "&amp;lt; &amp;amp; &quot; &apos; &lt; &gt;"
            "</file></files></repomix>"
        )
        self.assertEqual(parse_xml(raw)[0].content, "&lt; &amp; \" ' < >")

    def test_default_xml_does_not_decode_entity_like_text(self) -> None:
        raw = '<files>\n<file path="a.txt">\n&amp; &lt;\n</file>\n</files>'
        self.assertEqual(parse_xml(raw)[0].content, "&amp; &lt;")

    def test_unclosed_xml_entry_is_rejected(self) -> None:
        raw = '<files>\n<file path="a.txt">\nhello\n</files>'
        with self.assertRaises(UnmixError) as caught:
            parse_xml(raw)
        self.assertIn("Malformed", str(caught.exception))

    def test_duplicate_json_keys_are_rejected(self) -> None:
        raw = '{"files": {"a.txt": "x", "a.txt": "y"}}'
        with self.assertRaises(UnmixError) as caught:
            parse_repomix(raw, "json")
        self.assertIn("Duplicate JSON key", str(caught.exception))

    def test_unclosed_markdown_fence_is_rejected(self) -> None:
        raw = "## File: a.txt\n```\nunclosed\n"
        with self.assertRaises(UnmixError) as caught:
            parse_markdown(raw)
        self.assertIn("unclosed", str(caught.exception))

    def test_plain_text_style_is_not_detected(self) -> None:
        self.assertIsNone(
            detect_format(
                "This file is a merged representation of the entire codebase, combined "
                "into a single document by Repomix.\n\n"
                "================================================================\n"
                "File: a.txt\n"
                "================================================================\n"
            )
        )


if __name__ == "__main__":
    unittest.main()
